#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""deadnix reimplementation: find unused bindings in .nix files."""
import sys
sys.setrecursionlimit(100000)
import os
import re
import json
import stat as statmod
import unicodedata

VERSION = "deadnix 1.3.1"

# ---------------------------------------------------------------- utilities
def byte_len(s):
    return len(s.encode('utf-8', 'surrogatepass'))

def jaro(a,b):
    if a==b: return 1.0
    la,lb=len(a),len(b)
    if la==0 or lb==0: return 0.0
    match_dist=max(la,lb)//2-1
    if match_dist<0: match_dist=0
    a_matches=[False]*la; b_matches=[False]*lb
    matches=0
    for i in range(la):
        start=max(0,i-match_dist); end=min(i+match_dist+1,lb)
        for j in range(start,end):
            if not b_matches[j] and a[i]==b[j]:
                a_matches[i]=True; b_matches[j]=True; matches+=1; break
    if matches==0: return 0.0
    trans=0; k=0
    for i in range(la):
        if a_matches[i]:
            while not b_matches[k]: k+=1
            if a[i]!=b[k]: trans+=1
            k+=1
    return (matches/la+matches/lb+(matches-trans//2)/matches)/3.0

def jaro_winkler(a,b):
    j=jaro(a,b)
    prefix=0
    for x,y in zip(a,b):
        if x==y and prefix<4: prefix+=1
        else: break
    return j+prefix*0.1*(1-j)

def similar(word, candidates):
    best=None; bestscore=0.0
    for c in candidates:
        s=jaro_winkler(word,c)
        if s>bestscore:
            bestscore=s; best=c
    if best is not None and bestscore>0.8:
        return best
    return None

class Panic(Exception):
    def __init__(self, location, message):
        self.location=location; self.message=message

def emit_panic(location, message):
    sys.stdout.flush()
    pid=os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at {location}:\n{message}\n")
    sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.stderr.flush()

# ---------------------------------------------------------------- tokens
KEYWORDS={
    'let':'LET','in':'IN','if':'IF','then':'THEN','else':'ELSE','assert':'ASSERT',
    'with':'WITH','rec':'REC','inherit':'INHERIT','or':'OR',
}
PATH_CHARS=set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._+-")
URI_RE=re.compile(r"[a-zA-Z][a-zA-Z0-9+.\-]*:[a-zA-Z0-9%/?:@&=+$,.!~*'()_\-]+")
IDENT_RE=re.compile(r"[a-zA-Z_][a-zA-Z0-9_'\-]*")
SPATH_RE=re.compile(r"<[a-zA-Z0-9._+\-]+(?:/[a-zA-Z0-9._+\-]+)*>")
FLOAT_RE=re.compile(r"(?:[0-9]+\.[0-9]*(?:[eE][+-]?[0-9]+)?|[0-9]+[eE][+-]?[0-9]+|\.[0-9]+(?:[eE][+-]?[0-9]+)?)")
INT_RE=re.compile(r"[0-9]+")

class ParseError(Exception):
    def __init__(self, messages):
        if isinstance(messages,str): messages=[messages]
        self.messages=messages

class Token:
    __slots__=('kind','text','start','end','index')
    def __init__(self,kind,text,start,end,index=0):
        self.kind=kind; self.text=text; self.start=start; self.end=end; self.index=index
    def __repr__(self):
        return f"Tok({self.kind},{self.text!r},{self.start},{self.end})"

class Lexer:
    def __init__(self,text):
        self.text=text; self.n=len(text); self.pos=0
        self.tokens=[]
        # frames: dicts with mode; code frames may have interp=True and brace_depth
        self.frames=[{'mode':'code','interp':False,'depth':0}]
    def emit(self,kind,start,end):
        t=Token(kind,self.text[start:end],start,end,len(self.tokens))
        self.tokens.append(t)
        self.pos=end
        return t
    def tokenize(self):
        while self.pos<self.n:
            frame=self.frames[-1]
            mode=frame['mode']
            if mode=='dquote':
                self.lex_dquote()
            elif mode=='indented':
                self.lex_indented()
            elif mode=='path':
                if not self.lex_pathpart():
                    # path ended
                    self.frames.pop()
                    continue
            else:
                self.lex_code(frame)
        if len(self.frames)!=1:
            # unterminated string/path/interpolation
            raise ParseError("unexpected end of file")
        self.tokens.append(Token('EOF','',self.n,self.n,len(self.tokens)))
        return self.tokens
    # string scanners
    def lex_dquote(self):
        s=self.text; i=self.pos
        if s[i]=='"':
            self.emit('STRING_END',i,i+1); self.frames.pop(); return
        if s.startswith('${',i):
            self.emit('INTERP_START',i,i+2)
            self.frames.append({'mode':'code','interp':True,'depth':0}); return
        j=i
        while j<self.n:
            c=s[j]
            if c=='\\':
                j+=2 if j+1<self.n else 1
                continue
            if c=='"' or (c=='$' and j+1<self.n and s[j+1]=='{'):
                break
            j+=1
        if j==i:
            j=i+1
        self.emit('STRING_PART',i,j)
    def lex_indented(self):
        s=self.text; i=self.pos
        if s.startswith("''",i):
            nxt=s[i+2] if i+2<self.n else ''
            if nxt not in ("'",'$','\\'):
                self.emit('STRING_END',i,i+2); self.frames.pop(); return
        if s.startswith('${',i):
            self.emit('INTERP_START',i,i+2)
            self.frames.append({'mode':'code','interp':True,'depth':0}); return
        j=i
        while j<self.n:
            if s.startswith("'''",j):
                j+=3; continue
            if s.startswith("''$",j):
                j+=3; continue
            if s.startswith("''\\",j):
                j+=3
                if j<self.n: j+=1
                continue
            if s.startswith("''",j):
                break
            if s.startswith('${',j):
                break
            j+=1
        if j==i:
            j=i+1
        self.emit('STRING_PART',i,j)
    def lex_pathpart(self):
        s=self.text; i=self.pos
        if s.startswith('${',i):
            self.emit('INTERP_START',i,i+2)
            self.frames.append({'mode':'code','interp':True,'depth':0}); return True
        if i<self.n and (s[i] in PATH_CHARS or s[i]=='/' or s[i]=='~'):
            j=i
            while j<self.n and (s[j] in PATH_CHARS or s[j]=='/'):
                j+=1
            if j==i: # lone ~
                j=i+1
            self.emit('PATH_PART',i,j); return True
        return False
    def is_path_start(self,i):
        s=self.text; n=self.n
        if i>=n: return False
        c=s[i]
        # ~/
        if c=='~' and i+1<n and s[i+1]=='/':
            return True
        # absolute /
        if c=='/' and i+1<n and (s[i+1] in PATH_CHARS):
            return True
        # relative paths: scan first component (path chars), require / followed by comp or ${
        if c in PATH_CHARS:
            j=i
            while j<n and s[j] in PATH_CHARS:
                j+=1
            if j<n and s[j]=='/' :
                if j+1<n and (s[j+1] in PATH_CHARS or s.startswith('${',j+1)):
                    return True
            return False
        return False
    def lex_code(self,frame):
        s=self.text; i=self.pos; c=s[i]
        # whitespace
        if c in ' \t\r\n':
            j=i+1
            while j<self.n and s[j] in ' \t\r\n': j+=1
            self.emit('WS',i,j); return
        # comments
        if c=='#':
            j=s.find('\n',i)
            if j==-1: j=self.n
            self.emit('COMMENT',i,j); return
        if s.startswith('/*',i):
            j=s.find('*/',i+2)
            if j==-1:
                raise ParseError("unexpected end of file")
            self.emit('COMMENT',i,j+2); return
        # interpolation end
        if frame.get('interp') and c=='}' and frame['depth']==0:
            self.emit('INTERP_END',i,i+1); self.frames.pop(); return
        # strings
        if c=='"':
            self.emit('STRING_START',i,i+1)
            self.frames.append({'mode':'dquote'}); return
        if s.startswith("''",i):
            self.emit('STRING_START',i,i+2)
            self.frames.append({'mode':'indented'}); return
        # ${ dynamic
        if s.startswith('${',i):
            # bump brace depth? It is a brace-like opener closed by a plain } token.
            # In interp frame, ${ ... } inside code: its closing } should be DYNAMIC_END-ish }.
            # We track with a marker stack in frame.
            frame.setdefault('dyn',[]).append(True)
            if frame.get('interp'):
                frame['depth']+=1
            self.emit('DYNAMIC_START',i,i+2); return
        # spath
        if c=='<':
            m=SPATH_RE.match(s,i)
            if m:
                self.emit('SPATH',i,m.end()); return
        # path (check before ident/number/dot/slash), but after spath/comments
        # Number handled inside: path check requires slash; floats have no slash.
        if self.is_path_start(i):
            self.frames.append({'mode':'path'})
            # lex first part now in next loop
            return
        # URI before ident (only letters)
        if c.isalpha():
            m=URI_RE.match(s,i)
            if m:
                # ensure not just ident colon followed by something that made uri longer? regex requires rest char
                self.emit('URI',i,m.end()); return
        # numbers
        if c.isdigit() or (c=='.' and i+1<self.n and s[i+1].isdigit()):
            m=FLOAT_RE.match(s,i)
            if m and ('.' in m.group(0) or 'e' in m.group(0) or 'E' in m.group(0)):
                self.emit('FLOAT',i,m.end()); return
            m=INT_RE.match(s,i)
            if m:
                self.emit('INT',i,m.end()); return
        # identifiers / keywords
        if c.isalpha() or c=='_':
            m=IDENT_RE.match(s,i)
            if m:
                txt=m.group(0)
                kind=KEYWORDS.get(txt,'IDENT')
                self.emit(kind,i,m.end()); return
        # operators / punct, longest first
        multi=[
            ('...','ELLIPSIS'),('==','EQ'),('!=','NEQ'),('<=','LE'),('>=','GE'),
            ('&&','AND'),('||','OR_OP'),('->','IMPL'),('//','UPDATE'),('++','CONCAT'),
        ]
        for txt,kind in multi:
            if s.startswith(txt,i):
                self.emit(kind,i,i+len(txt)); return
        single={
            '(':'L_PAREN',')':'R_PAREN','[':'L_BRACK',']':'R_BRACK','{':'L_BRACE','}':'R_BRACE',
            ',':'COMMA',':':'COLON',';':'SEMICOLON','=':'ASSIGN','@':'AT','?':'QUESTION',
            '.':'DOT','+':'PLUS','-':'MINUS','*':'MUL','/':'DIV','!':'NOT','<':'LESS','>':'GREATER',
        }
        if c in single:
            kind=single[c]
            if frame.get('interp'):
                if kind=='L_BRACE': frame['depth']+=1
                elif kind=='R_BRACE' and frame['depth']>0: frame['depth']-=1
            self.emit(kind,i,i+1); return
        # unknown char
        raise ParseError(f"unexpected token at {byte_len(s[:i])}..{byte_len(s[:i+1])}")

# ---------------------------------------------------------------- AST
class Node:
    def __init__(self,kind,start,end,**kw):
        self.kind=kind; self.start=start; self.end=end
        for k,v in kw.items(): setattr(self,k,v)
    def __repr__(self):
        return f"Node({self.kind},{self.start},{self.end})"

class Attr:
    def __init__(self,kind,start,end,token=None,name=None,node=None,expr=None):
        self.kind=kind; self.start=start; self.end=end; self.token=token; self.name=name; self.node=node; self.expr=expr

class Entry:
    def __init__(self,kind,start,end,**kw):
        self.kind=kind; self.start=start; self.end=end
        self.attrpath=[]; self.value=None; self.from_expr=None; self.attrs=[]
        self.semicolon=None; self.binding=None; self.bindings=[]; self.inherit_tok=None
        for k,v in kw.items(): setattr(self,k,v)

class Parser:
    def __init__(self,text,tokens):
        self.text=text
        self.all_tokens=tokens
        self.sig=[t for t in tokens if t.kind not in ('WS','COMMENT')]
        self.pos=0
    def peek(self,off=0):
        i=self.pos+off
        if i<len(self.sig): return self.sig[i]
        return self.sig[-1]
    def at(self,kind):
        return self.peek().kind==kind
    def text_at(self,txt):
        return self.peek().text==txt
    def advance(self):
        t=self.peek(); 
        if self.pos<len(self.sig)-1: self.pos+=1
        return t
    def accept(self,kind):
        if self.at(kind): return self.advance()
        return None
    def expect(self,kind):
        if self.at(kind): return self.advance()
        t=self.peek()
        if t.kind=='EOF':
            raise ParseError("unexpected end of file")
        raise ParseError(f"unexpected token at {byte_len(self.text[:t.start])}..{byte_len(self.text[:t.end])}")
    def error_eof(self):
        raise ParseError("unexpected end of file")
    # entry
    def parse(self):
        if self.at('EOF'):
            raise ParseError("unexpected end of file")
        expr=self.parse_expr()
        if not self.at('EOF'):
            t=self.peek()
            raise ParseError(f"unexpected token at {byte_len(self.text[:t.start])}..{byte_len(self.text[:t.end])}")
        return expr
    # full expression (function level)
    def parse_expr(self):
        t=self.peek()
        # let
        if t.kind=='LET':
            # legacy let { ... }
            # peek next sig token; if { then legacy (but a let-in can also have? let { is legacy in Nix/rnix)
            if self.peek(1).kind=='L_BRACE':
                start=self.advance()  # let
                aset=self.parse_attrset()
                return Node('LegacyLet',start.start,aset.end,body=aset)
            return self.parse_let()
        if t.kind=='IF':
            start=self.advance(); cond=self.parse_expr(); self.expect('THEN'); then=self.parse_expr(); self.expect('ELSE'); els=self.parse_expr()
            return Node('If',start.start,els.end,cond=cond,then=then,els=els,children=[cond,then,els])
        if t.kind=='ASSERT':
            start=self.advance(); cond=self.parse_op_expr(); self.expect('SEMICOLON'); body=self.parse_expr()
            return Node('Assert',start.start,body.end,cond=cond,body=body,children=[cond,body])
        if t.kind=='WITH':
            start=self.advance(); env=self.parse_op_expr(); self.expect('SEMICOLON'); body=self.parse_expr()
            return Node('With',start.start,body.end,env=env,body=body,children=[env,body])
        # lambda simple: IDENT :
        if t.kind=='IDENT' and self.peek(1).kind=='COLON':
            arg=self.advance(); colon=self.advance(); body=self.parse_expr()
            return Node('Lambda',arg.start,body.end,arg_tok=arg,colon=colon,body=body,pattern=None,at_tok=None,at_name=None)
        # lambda pattern attempted
        lam=self.try_parse_pattern_lambda()
        if lam is not None:
            return lam
        return self.parse_op_expr()
    def try_parse_pattern_lambda(self):
        save=self.pos
        try:
            return self.parse_pattern_lambda()
        except ParseError:
            self.pos=save
            return None
    def parse_pattern_lambda(self):
        starttok=self.peek()
        at_name=None; at_tok=None; at_side=None
        pattern_start=None; pattern_end=None; lb=None; rb=None
        # IDENT @ { ... }
        if self.peek().kind=='IDENT' and self.peek(1).kind=='AT':
            at_name=self.advance(); at_tok=self.advance(); at_side='left'
            lb=self.expect('L_BRACE')
        elif self.peek().kind=='L_BRACE':
            lb=self.advance()
        else:
            raise ParseError("not pattern")
        entries=[]; ellipsis=None
        # entries
        while True:
            if self.at('R_BRACE'):
                rb=self.advance(); break
            if self.at('ELLIPSIS'):
                ellipsis=self.advance()
                # optional comma after ellipsis? (grammar: ... maybe trailing)
                self.accept('COMMA')
                if self.at('R_BRACE'):
                    rb=self.advance(); break
                else:
                    # ellipsis not at end -> not a valid pattern, will fail later
                    continue
            if self.at('EOF'):
                self.error_eof()
            name=self.expect('IDENT')
            default=None; q=None; end=name.end
            if self.at('QUESTION'):
                q=self.advance(); default=self.parse_expr(); end=default.end
            e=Node('PatEntry',name.start,end,name_tok=name,default=default,question=q,binding=None)
            entries.append(e)
            if self.at('COMMA'):
                self.advance(); continue
            elif self.at('R_BRACE'):
                rb=self.advance(); break
            else:
                # missing comma
                t=self.peek(); raise ParseError(f"unexpected token at {byte_len(self.text[:t.start])}..{byte_len(self.text[:t.end])}")
        if at_side is None and self.at('AT'):
            at_tok=self.advance(); at_name=self.expect('IDENT'); at_side='right'
        if not self.at('COLON'):
            raise ParseError("not pattern no colon")
        colon=self.advance(); body=self.parse_expr()
        start = at_name.start if (at_side=='left' and at_name is not None) else lb.start
        pat=Node('Pattern',lb.start,rb.end,entries=entries,ellipsis=ellipsis,lbrace=lb,rbrace=rb)
        return Node('Lambda',start,body.end,arg_tok=None,colon=colon,body=body,pattern=pat,at_tok=at_tok,at_name=at_name,at_side=at_side)
    def parse_let(self):
        let_tok=self.expect('LET')
        entries=self.parse_binding_entries(end_kind='IN')
        in_tok=self.expect('IN')
        body=self.parse_expr()
        return Node('LetIn',let_tok.start,body.end,let_tok=let_tok,in_tok=in_tok,entries=entries,body=body)
    def parse_attrset(self):
        rec_tok=None
        if self.at('REC') and self.peek(1).kind=='L_BRACE':
            rec_tok=self.advance()
        lb=self.expect('L_BRACE')
        entries=self.parse_binding_entries(end_kind='R_BRACE')
        rb=self.expect('R_BRACE')
        start=rec_tok.start if rec_tok else lb.start
        return Node('AttrSet',start,rb.end,rec_tok=rec_tok,lbrace=lb,rbrace=rb,entries=entries,is_rec=rec_tok is not None)
    def parse_binding_entries(self,end_kind):
        entries=[]
        while not self.at(end_kind):
            if self.at('EOF'):
                self.error_eof()
            if self.at('INHERIT'):
                entries.append(self.parse_inherit())
            else:
                entries.append(self.parse_attr_value())
        return entries
    def parse_inherit(self):
        it=self.expect('INHERIT')
        from_expr=None
        if self.at('L_PAREN'):
            self.advance(); from_expr=self.parse_expr(); self.expect('R_PAREN')
        attrs=[]
        while not self.at('SEMICOLON'):
            if self.at('EOF'): self.error_eof()
            attrs.append(self.parse_attr())
        semi=self.expect('SEMICOLON')
        e=Entry('inherit',it.start,semi.end,inherit_tok=it,from_expr=from_expr,attrs=attrs,semicolon=semi)
        return e
    def parse_attr_value(self):
        path=[self.parse_attr()]
        while self.at('DOT'):
            self.advance(); path.append(self.parse_attr())
        self.expect('ASSIGN')
        value=self.parse_expr()
        semi=self.expect('SEMICOLON')
        e=Entry('value',path[0].start,semi.end,attrpath=path,value=value,semicolon=semi)
        return e
    def parse_attr(self):
        t=self.peek()
        if t.kind=='IDENT':
            self.advance(); return Attr('ident',t.start,t.end,token=t,name=t.text)
        if t.kind=='OR':
            self.advance(); return Attr('ident',t.start,t.end,token=t,name=t.text)
        if t.kind=='STRING_START':
            s=self.parse_string(); return Attr('string',s.start,s.end,node=s)
        if t.kind=='DYNAMIC_START':
            start=self.advance(); expr=self.parse_expr(); end=self.expect('R_BRACE'); return Attr('dynamic',start.start,end.end,expr=expr)
        if t.kind=='EOF': self.error_eof()
        raise ParseError(f"unexpected token at {byte_len(self.text[:t.start])}..{byte_len(self.text[:t.end])}")
    def parse_string(self):
        start=self.expect('STRING_START')
        parts=[]
        while True:
            if self.at('STRING_END'):
                end=self.advance(); break
            if self.at('STRING_PART'):
                self.advance(); continue
            if self.at('INTERP_START'):
                self.advance(); e=self.parse_expr(); self.expect('INTERP_END'); parts.append(e); continue
            if self.at('EOF'): self.error_eof()
            t=self.peek(); raise ParseError(f"unexpected token at {byte_len(self.text[:t.start])}..{byte_len(self.text[:t.end])}")
        return Node('String',start.start,end.end,parts=parts,children=parts)
    def parse_path(self):
        first=self.peek()
        parts=[]; start=first.start; end=first.end
        while True:
            if self.at('PATH_PART'):
                tk=self.advance(); end=tk.end; continue
            if self.at('INTERP_START'):
                self.advance(); e=self.parse_expr(); tk=self.expect('INTERP_END'); parts.append(e); end=tk.end; continue
            break
        return Node('Path',start,end,parts=parts,children=parts)
    # operator precedence
    # levels low->high as list of (ops, assoc)
    # We'll implement parse_op_expr for binary ops above application.
    BIN_LEVELS=[
        (['IMPL'],'right'),
        (['OR_OP'],'left'),
        (['AND'],'left'),
        (['EQ','NEQ'],'left'),
        (['LESS','GREATER','LE','GE'],'left'),
        (['UPDATE'],'right'),
        (['CONCAT'],'right'),
        (['PLUS','MINUS'],'left'),
        (['MUL','DIV'],'left'),
    ]
    def parse_op_expr(self,level=0):
        if level>=len(self.BIN_LEVELS):
            return self.parse_unary()
        ops,assoc=self.BIN_LEVELS[level]
        # '!' is a prefix at a level between update and concat in Nix; treat in unary below anyway
        left=self.parse_op_expr(level+1)
        while self.peek().kind in ops:
            op=self.advance()
            if assoc=='right':
                right=self.parse_op_expr(level)
            else:
                right=self.parse_op_expr(level+1)
            left=Node('Binary',left.start,right.end,op=op,left=left,right=right,children=[left,right])
            if assoc=='right': break
        return left
    def parse_unary(self):
        if self.at('NOT'):
            op=self.advance(); e=self.parse_unary(); return Node('Unary',op.start,e.end,op=op,expr=e,children=[e])
        if self.at('MINUS'):
            op=self.advance(); e=self.parse_unary(); return Node('Unary',op.start,e.end,op=op,expr=e,children=[e])
        return self.parse_has_attr()
    def parse_has_attr(self):
        left=self.parse_apply()
        if self.at('QUESTION'):
            # could conflict with pattern default ? but in expr context parse_expr for defaults calls parse_expr->...->this;
            # a ? b where b is attrpath. If no valid attr following, backtrack? parser expects attr.
            # However this is also called when parsing pattern default value end? Pattern parser consumes ? before default.
            q=self.advance(); attrs=[self.parse_attr()]
            while self.at('DOT'):
                self.advance(); attrs.append(self.parse_attr())
            return Node('HasAttr',left.start,attrs[-1].end,expr=left,attrs=attrs,children=[left])
        return left
    def parse_apply(self):
        func=self.parse_select()
        while True:
            # next token can start a select-level argument
            if self.can_start_select():
                arg=self.parse_select()
                func=Node('Apply',func.start,arg.end,func=func,arg=arg,children=[func,arg])
            else:
                break
        return func
    def can_start_select(self):
        k=self.peek().kind
        return k in ('IDENT','INT','FLOAT','STRING_START','URI','SPATH','PATH_PART','L_PAREN','L_BRACE','REC','L_BRACK')
    def parse_select(self):
        base=self.parse_primary()
        attrs=[]
        while self.at('DOT'):
            self.advance(); attrs.append(self.parse_attr())
        if attrs:
            default=None; end=attrs[-1].end
            if self.at('OR'):
                self.advance(); default=self.parse_select(); end=default.end
            return Node('Select',base.start,end,expr=base,attrs=attrs,default=default,children=([base]+([default] if default else [])))
        return base
    def parse_primary(self):
        t=self.peek()
        if t.kind=='IDENT':
            self.advance(); return Node('Var',t.start,t.end,token=t,name=t.text)
        if t.kind in ('INT','FLOAT','URI','SPATH'):
            self.advance(); return Node('Literal',t.start,t.end,token=t)
        if t.kind=='STRING_START':
            return self.parse_string()
        if t.kind=='PATH_PART':
            return self.parse_path()
        if t.kind=='L_PAREN':
            start=self.advance(); e=self.parse_expr(); end=self.expect('R_PAREN'); return Node('Paren',start.start,end.end,expr=e,children=[e])
        if t.kind=='L_BRACK':
            start=self.advance(); elems=[]
            while not self.at('R_BRACK'):
                if self.at('EOF'): self.error_eof()
                elems.append(self.parse_select())
            end=self.advance(); return Node('List',start.start,end.end,elems=elems,children=elems)
        if t.kind=='REC' and self.peek(1).kind=='L_BRACE':
            return self.parse_attrset()
        if t.kind=='L_BRACE':
            return self.parse_attrset()
        if t.kind=='LET':
            # let expression as primary can occur? via parse_expr usually. allow
            return self.parse_expr()
        if t.kind=='EOF':
            self.error_eof()
        raise ParseError(f"unexpected token at {byte_len(self.text[:t.start])}..{byte_len(self.text[:t.end])}")

# ---------------------------------------------------------------- analysis
class Binding:
    _counter=0
    def __init__(self,scope,name,token,kind,node=None,entry=None):
        Binding._counter+=1; self.id=Binding._counter
        self.scope=scope; self.name=name; self.token=token; self.kind=kind; self.node=node; self.entry=entry
        self.root_live=False; self.live=False; self.deps=set(); self.exempt=False
    def __repr__(self):
        return f"B({self.kind},{self.name}@{self.token.start if self.token else '?'})"

class Scope:
    def __init__(self,kind,node):
        self.kind=kind; self.node=node; self.bindings=[]; self.by_name={}
    def add(self,b):
        self.bindings.append(b); self.by_name.setdefault(b.name,[]).append(b); return b

PSEUDO_DEAD = object()

class Analyzer:
    def __init__(self,text,root,comments,opts):
        self.text=text; self.root=root; self.comments=comments; self.opts=opts
        self.all_bindings=[]; self.frames=[]  # each: [scope, owner] mutable
        # line starts for skip calc
        self.line_starts=[0]
        for i,ch in enumerate(text):
            if ch=='\n': self.line_starts.append(i+1)
    def line_of(self,pos):
        import bisect
        return bisect.bisect_right(self.line_starts,pos)  # 1-based
    def is_skipped(self,token):
        if token is None: return False
        line=self.line_of(token.start)
        for (cstart,cend) in self.comments:
            if cend<=token.start:
                cline=self.line_of(cend)
                # comment end could be at a \n char position? line_of(end) : if end points at \n, bisect gives that line
                if line==cline or line==cline+1:
                    return True
        return False
    def new_binding(self,scope,name,token,kind,node=None,entry=None):
        b=Binding(scope,name,token,kind,node,entry); scope.add(b); self.all_bindings.append(b)
        # exempt determination (seed)
        if self.is_skipped(token):
            b.exempt=True
        elif kind=='let' and self.opts['no_underscore'] and name.startswith('_'):
            b.exempt=True
        elif kind=='lambda_arg' and (self.opts['no_lambda_arg'] or name.startswith('_')):
            b.exempt=True
        elif kind=='pattern_entry' and (self.opts['no_lambda_pattern_names'] or (self.opts['no_underscore'] and name.startswith('_'))):
            b.exempt=True
        elif kind=='pattern_at' and self.opts['no_underscore'] and name.startswith('_'):
            b.exempt=True
        if b.exempt:
            b.root_live=True
        return b
    def resolve_usage(self,name,skip_scope=None):
        # walk frames innermost->outermost
        for frame in reversed(self.frames):
            scope=frame[0]; owner=frame[1]
            if skip_scope is not None and scope is skip_scope:
                continue
            targets=scope.by_name.get(name)
            if targets:
                if owner is None:
                    for tg in targets: tg.root_live=True
                elif owner is PSEUDO_DEAD:
                    pass
                else:
                    owners=owner if isinstance(owner,list) else [owner]
                    for ow in owners:
                        if isinstance(ow,Binding):
                            for tg in targets:
                                ow.deps.add(tg)
                return
    def set_owner(self,scope,owner):
        for frame in reversed(self.frames):
            if frame[0] is scope:
                frame[1]=owner; return
    def analyze(self):
        root_scope=Scope('root',self.root)
        self.frames.append([root_scope,None])
        self.visit(self.root)
        self.frames.pop()
        # propagate liveness
        work=[]
        for b in self.all_bindings:
            if b.root_live or b.kind=='rec':
                if not b.live:
                    b.live=True; work.append(b)
        while work:
            b=work.pop()
            for tg in b.deps:
                if not tg.live:
                    tg.live=True; work.append(tg)
        # results
        results=[]
        for b in self.all_bindings:
            r=self.make_result(b)
            if r is not None:
                results.append(r)
        results.sort(key=lambda r:(r['binding'].token.start, r['binding'].token.end))
        return results
    def make_result(self,b):
        if b.kind in ('rec','pseudo'): return None
        if self.is_skipped(b.token): return None
        name=b.name
        if b.kind=='let':
            if self.opts['no_underscore'] and name.startswith('_'): return None
            if self.opts['warn_used_underscore'] and name.startswith('_') and b.live:
                return {'binding':b,'used':True,'message':f"Used let binding: {name}"}
            if not b.live:
                return {'binding':b,'used':False,'message':f"Unused let binding: {name}"}
        elif b.kind=='lambda_arg':
            if self.opts['no_lambda_arg']: return None
            if name.startswith('_'): return None
            if not b.live:
                return {'binding':b,'used':False,'message':f"Unused lambda argument: {name}"}
        elif b.kind=='pattern_entry':
            if self.opts['no_lambda_pattern_names']: return None
            if self.opts['no_underscore'] and name.startswith('_'): return None
            if self.opts['warn_used_underscore'] and name.startswith('_') and b.live:
                return {'binding':b,'used':True,'message':f"Used lambda pattern: {name}"}
            if not b.live:
                return {'binding':b,'used':False,'message':f"Unused lambda pattern: {name}"}
        elif b.kind=='pattern_at':
            if self.opts['no_underscore'] and name.startswith('_'): return None
            if self.opts['warn_used_underscore'] and name.startswith('_') and b.live:
                return {'binding':b,'used':True,'message':f"Used lambda pattern: {name}"}
            if not b.live:
                return {'binding':b,'used':False,'message':f"Unused lambda pattern: {name}"}
        return None
    # ---- traversal
    def visit(self,node):
        if node is None: return
        k=node.kind
        if k=='Var':
            self.resolve_usage(node.name); return
        if k=='Literal' or k=='SPATH':
            return
        if k=='String' or k=='Path':
            for p in node.parts: self.visit(p)
            return
        if k=='LetIn':
            self.visit_let(node); return
        if k=='Lambda':
            self.visit_lambda(node); return
        if k=='AttrSet':
            self.visit_attrset(node); return
        if k=='LegacyLet':
            self.visit(node.body); return
        if k=='Select':
            self.visit(node.expr)
            for a in node.attrs: self.visit_attr_desc(a)
            if getattr(node,'default',None) is not None: self.visit(node.default)
            return
        if k=='HasAttr':
            self.visit(node.expr)
            for a in node.attrs: self.visit_attr_desc(a)
            return
        # generic children
        children=getattr(node,'children',None)
        if children is not None:
            for c in children: self.visit(c)
            return
        # fallback: look for common fields
        for attr in ('expr','body','cond','then','els','env','func','arg','left','right'):
            v=getattr(node,attr,None)
            if isinstance(v,Node): self.visit(v)
    def visit_attr_desc(self,attr):
        if attr.kind=='string':
            if attr.node is not None: self.visit(attr.node)
        elif attr.kind=='dynamic':
            if attr.expr is not None: self.visit(attr.expr)
        # ident: not usage
    def visit_let(self,node):
        scope=Scope('let',node); node.scope=scope
        # create bindings
        for e in node.entries:
            if e.kind=='value':
                first=e.attrpath[0]
                if first.kind=='ident':
                    b=self.new_binding(scope,first.name,first.token,'let',node=e,entry=e); e.binding=b; e.bindings=[b]
                else:
                    e.binding=None; e.bindings=[]
            else: # inherit
                e.bindings=[]
                for a in e.attrs:
                    if a.kind=='ident':
                        b=self.new_binding(scope,a.name,a.token,'let',node=e,entry=e); e.bindings.append(b)
                        a.binding=b
        self.frames.append([scope,None])
        for e in node.entries:
            if e.kind=='value':
                if e.binding is not None:
                    self.set_owner(scope,e.binding)
                else:
                    self.set_owner(scope,None)
                for a in e.attrpath:
                    self.visit_attr_desc(a)
                self.visit(e.value)
            else:
                if e.from_expr is not None:
                    if len(e.attrs)==0:
                        self.set_owner(scope,PSEUDO_DEAD)
                        self.visit(e.from_expr)
                    elif len(e.bindings)==0:
                        self.set_owner(scope,None)
                        self.visit(e.from_expr)
                    else:
                        self.set_owner(scope,e.bindings)
                        self.visit(e.from_expr)
                    # attr descriptors not traversed
                else:
                    # plain inherit
                    for a in e.attrs:
                        if a.kind=='ident':
                            # usage in enclosing scope(s); current scope owner restore to None doesn't matter (skipped)
                            self.resolve_usage(a.name,skip_scope=scope)
                        else:
                            self.set_owner(scope,PSEUDO_DEAD)
                            self.visit_attr_desc(a)
                self.set_owner(scope,None)
        self.set_owner(scope,None)
        self.visit(node.body)
        self.frames.pop()
    def visit_lambda(self,node):
        if node.arg_tok is not None:
            scope=Scope('lambda_arg',node); node.scope=scope
            b=self.new_binding(scope,node.arg_tok.text,node.arg_tok,'lambda_arg',node=node); node.binding=b
            self.frames.append([scope,None]); self.visit(node.body); self.frames.pop()
        else:
            scope=Scope('lambda_pattern',node); node.scope=scope
            pat=node.pattern
            # at binding
            node.at_binding=None
            if node.at_name is not None:
                node.at_binding=self.new_binding(scope,node.at_name.text,node.at_name,'pattern_at',node=node)
            # entries; handle duplicates: duplicate names get exempt/live
            names={}
            for e in pat.entries:
                names[e.name_tok.text]=names.get(e.name_tok.text,0)+1
            for e in pat.entries:
                b=self.new_binding(scope,e.name_tok.text,e.name_tok,'pattern_entry',node=e); e.binding=b
                if names[e.name_tok.text]>1:
                    b.exempt=True; b.root_live=True
            self.frames.append([scope,None])
            for e in pat.entries:
                if e.default is not None:
                    self.set_owner(scope,e.binding)
                    self.visit(e.default)
            self.set_owner(scope,None)
            self.visit(node.body)
            self.frames.pop()
    def visit_attrset(self,node):
        if node.is_rec:
            scope=Scope('rec',node); node.scope=scope
            for e in node.entries:
                if e.kind=='value':
                    first=e.attrpath[0]
                    if first.kind=='ident':
                        b=Binding(scope,first.name,first.token,'rec',node=e,entry=e); scope.add(b); self.all_bindings.append(b); e.binding=b; e.bindings=[b]
                    else:
                        e.binding=None; e.bindings=[]
                else:
                    e.bindings=[]
                    for a in e.attrs:
                        if a.kind=='ident':
                            b=Binding(scope,a.name,a.token,'rec',node=e,entry=e); scope.add(b); self.all_bindings.append(b); e.bindings.append(b); a.binding=b
            self.frames.append([scope,None])
            for e in node.entries:
                if e.kind=='value':
                    for a in e.attrpath: self.visit_attr_desc(a)
                    self.visit(e.value)
                else:
                    if e.from_expr is not None:
                        # from expr is in outer scope: temporarily pop rec frame
                        recframe=self.frames.pop()
                        self.visit(e.from_expr)
                        self.frames.append(recframe)
                        for a in e.attrs:
                            if a.kind!='ident': self.visit_attr_desc(a)
                    else:
                        for a in e.attrs:
                            if a.kind=='ident':
                                self.resolve_usage(a.name,skip_scope=scope)
                            else:
                                self.visit_attr_desc(a)
            self.frames.pop()
        else:
            for e in node.entries:
                if e.kind=='value':
                    for a in e.attrpath: self.visit_attr_desc(a)
                    self.visit(e.value)
                else:
                    if e.from_expr is not None:
                        self.visit(e.from_expr)
                        for a in e.attrs:
                            if a.kind!='ident': self.visit_attr_desc(a)
                    else:
                        for a in e.attrs:
                            if a.kind=='ident':
                                self.resolve_usage(a.name)
                            else:
                                self.visit_attr_desc(a)

PY
"}

