    # ---- traversal
    def visit(self,node):
        if node is None: return
        k=node.kind
        if k=='Var':
            self.resolve_usage(node.name); return
        if k=='Literal' or k=='SPATH':
            return
        if k=='String' or k=='Path':
            for p in node.parts: self.visit(p)
