        for e in node.entries:
            if e.kind=='value':
                if e.binding is not None:
                    self.set_owner(scope,e.binding)
                else:
                    self.set_owner(scope,None)
                for a in e.attrpath:
                    self.visit_attr_desc(a)
                self.visit(e.value)
            else:
                if e.from_expr is not None:
                    if len(e.attrs)==0:
                        self.set_owner(scope,PSEUDO_DEAD)
                        self.visit(e.from_expr)
                    elif len(e.bindings)==0:
                        self.set_owner(scope,None)
                        self.visit(e.from_expr)
                    else:
                        self.set_owner(scope,e.bindings)
                        self.visit(e.from_expr)
