                    self.set_owner(scope,e.binding)
                    self.visit(e.default)
            self.set_owner(scope,None)
            self.visit(node.body)
            self.frames.pop()
    def visit_attrset(self,node):
        if node.is_rec:
            scope=Scope('rec',node); node.scope=scope
            for e in node.entries:
                if e.kind=='value':
                    first=e.attrpath[0]
                    if first.kind=='ident':
