                    for a in e.attrpath: self.visit_attr_desc(a)
                    self.visit(e.value)
                else:
                    if e.from_expr is not None:
                        self.visit(e.from_expr)
                        for a in e.attrs:
                            if a.kind!='ident': self.visit_attr_desc(a)
                    else:
                        for a in e.attrs:
                            if a.kind=='ident':
                                self.resolve_usage(a.name)
                            else:
                                self.visit_attr_desc(a)

