                self.emit('STRING_END',i,i+2); self.frames.pop(); return
        if s.startswith('${',i):
            self.emit('INTERP_START',i,i+2)
            self.frames.append({'mode':'code','interp':True,'depth':0}); return
        j=i
        while j<self.n:
            if s.startswith("'''",j):
                j+=3; continue
            if s.startswith("''$",j):
                j+=3; continue
            if s.startswith("''\\",j):
                j+=3
                if j<self.n: j+=1
                continue
            if s.startswith("''",j):
                break
            if s.startswith('${',j):
