        if c=='~' and i+1<n and s[i+1]=='/':
            return True
        # absolute /
        if c=='/' and i+1<n and (s[i+1] in PATH_CHARS):
            return True
        # relative paths: scan first component (path chars), require / followed by comp or ${
        if c in PATH_CHARS:
            j=i
            while j<n and s[j] in PATH_CHARS:
