    def line_col(self,pos):
        import bisect
        idx=bisect.bisect_right(self.line_starts,pos)-1
        start=self.line_starts[idx]
        col=byte_len(self.text[start:pos])+1
        return (idx+1,col,start)
    def line_text(self,line): # 1-based
        if line-1>=len(self.line_starts): return ""
        start=self.line_starts[line-1]
        end=self.text.find('\n',start)
        if end==-1: end=len(self.text)
        s=self.text[start:end]
        if s.endswith('\r'): s=s[:-1]
        # ariadne appears to cut at lone \r as well
        # s=s.split('\r',1)[0] if '\r' in s else s
        return s

def char_width(ch):
    if ch=='\t': return 4  # placeholder, handled contextually
    if unicodedata.combining(ch): return 0
    if unicodedata.east_asian_width(ch) in ('W','F'): return 2
    return 1

def expand_line(s):
    """return (expanded_string, list_of_(display_start,width,src_char) per src char index, total_width)"""
    out=[]; info=[]; col=0
