# ---------------------------------------------------------------- editing
class Editor:
    def __init__(self,text,root,all_tokens,results):
        self.text=text; self.root=root; self.tokens=[t for t in all_tokens if t.kind!='EOF']
        self.result_bindings={r['binding'].id for r in results}
        self.ops=[]  # (start,end,repl)
    def is_removed(self,b):
        return b is not None and b.id in self.result_bindings
    def prev_non_ws(self,pos):
        best=None
        for t in self.tokens:
            if t.kind=='WS': continue
            if t.end<=pos:
                if best is None or t.start>best.start: best=t
        return best
    def next_non_ws(self,pos):
        best=None
        for t in self.tokens:
            if t.kind=='WS': continue
            if t.start>=pos:
                if best is None or t.start<best.start: best=t
        return best
    def add(self,start,end,repl=''):
        self.ops.append((start,end,repl))
    def produce(self):
        self.gen(self.root)
        return self.apply()
    def apply(self):
        ops=sorted(self.ops,key=lambda o:(o[0],o[1]))
        out=[]; last=0
        for (s,e,repl) in ops:
            if s<last:
                last_b=byte_len(self.text[:last]); s_b=byte_len(self.text[:s])
                raise Panic("src/edit.rs:20:33", f"begin <= end ({last_b} <= {s_b}) when slicing `{self.text}`")
            out.append(self.text[last:s]); out.append(repl); last=e
        out.append(self.text[last:])
        return ''.join(out)
    # removal helpers
    def remove_entry(self,entry):
        prev=self.prev_non_ws(entry.start)
        start=prev.end if prev else entry.start
        self.add(start,entry.semicolon.end,'')
    def entry_fully_removed(self,e):
        if e.kind=='value':
            return self.is_removed(e.binding)
        else:
            if len(e.attrs)==0: return True
            if all(a.kind=='ident' for a in e.attrs) and e.bindings and all(self.is_removed(b) for b in e.bindings):
                # also ensure bindings cover all attrs
                return len(e.bindings)==len(e.attrs)
            return False
    def gen(self,node):
        if node is None: return
        k=node.kind
        if k=='LetIn':
            self.gen_let(node); return
        if k=='Lambda':
            self.gen_lambda(node); return
        if k=='AttrSet':
            self.gen_attrset(node); return
        if k=='LegacyLet':
            self.gen(node.body); return
        if k=='String' or k=='Path':
            for p in node.parts: self.gen(p)
            return
        if k=='Select':
            self.gen(node.expr)
            for a in node.attrs: self.gen_attr_desc(a)
            if getattr(node,'default',None) is not None: self.gen(node.default)
            return
        if k=='HasAttr':
            self.gen(node.expr)
            for a in node.attrs: self.gen_attr_desc(a)
            return
        children=getattr(node,'children',None)
        if children is not None:
            for c in children: self.gen(c)
            return
        for attr in ('expr','body'):
            v=getattr(node,attr,None)
            if isinstance(v,Node): self.gen(v)
    def gen_attr_desc(self,a):
        if a.kind=='string' and a.node is not None: self.gen(a.node)
        elif a.kind=='dynamic' and a.expr is not None: self.gen(a.expr)
    def gen_let(self,node):
        all_removed=False
        if len(node.entries)==0:
            all_removed=True
        elif all(self.entry_fully_removed(e) for e in node.entries):
            all_removed=True
        if all_removed:
            # bug emulation: entries all value-kind and no trivia between last ; and in
            bug=False
            if node.entries and all(e.kind=='value' for e in node.entries):
                last=node.entries[-1]
                if last.semicolon is not None and last.semicolon.end==node.in_tok.start:
                    bug=True
            if not bug:
                self.add(node.let_tok.start,node.body.start,'')
                self.gen(node.body)
                return
        # otherwise per-entry
        for e in node.entries:
            if e.kind=='value':
                if self.is_removed(e.binding):
                    self.remove_entry(e)
                else:
                    for a in e.attrpath: self.gen_attr_desc(a)
                    self.gen(e.value)
            else:
                if self.entry_fully_removed(e):
                    self.remove_entry(e)
                else:
                    if e.from_expr is not None: self.gen(e.from_expr)
                    # individual name removals
                    for a,b in _pair_inherit_bindings(e):
                        if self.is_removed(b):
                            prev=self.prev_non_ws(a.token.start)
                            start=prev.end if prev else a.token.start
                            self.add(start,a.token.end,'')
                    for a in e.attrs:
                        if a.kind!='ident': self.gen_attr_desc(a)
        self.gen(node.body)
    def gen_lambda(self,node):
        if node.arg_tok is not None:
            b=getattr(node,'binding',None)
            if self.is_removed(b):
                self.add(node.arg_tok.start,node.arg_tok.start,'_')
            self.gen(node.body); return
        pat=node.pattern
        # @ removal
        if getattr(node,'at_binding',None) is not None and self.is_removed(node.at_binding):
            if node.at_side=='left':
                after=self.next_non_ws(node.at_tok.end)
                end=after.start if after else node.at_tok.end
                self.add(node.at_name.start,end,'')
            else:
                before=self.prev_non_ws(node.at_tok.start)
                start=before.end if before else node.at_tok.start
                self.add(start,node.at_name.end,'')
        for e in pat.entries:
            b=getattr(e,'binding',None)
            if self.is_removed(b):
                self.remove_pat_entry(e)
            else:
                if e.default is not None: self.gen(e.default)
        self.gen(node.body)
    def remove_pat_entry(self,e):
        prev=self.prev_non_ws(e.start)
        nxt=self.next_non_ws(e.end)
        if nxt is not None and nxt.kind=='COMMA':
            start=prev.end if prev else e.start
            self.add(start,nxt.end,'')
        elif prev is not None and prev.kind=='COMMA':
            if nxt is not None and nxt.kind=='R_BRACE':
                self.add(prev.start,e.end,'')
            else:
                self.add(prev.end,e.end,'')
        else:
            if prev is not None and prev.kind=='COMMENT':
                self.add(prev.end,e.end,'')
            else:
                self.add(e.start,e.end,'')
    def gen_attrset(self,node):
        for e in node.entries:
            if e.kind=='value':
                for a in e.attrpath: self.gen_attr_desc(a)
                self.gen(e.value)
            else:
                if len(e.attrs)==0:
                    self.remove_entry(e)
                else:
                    if e.from_expr is not None: self.gen(e.from_expr)
                    for a in e.attrs:
                        if a.kind!='ident': self.gen_attr_desc(a)

def _pair_inherit_bindings(e):
    pairs=[]
    bi=0
    for a in e.attrs:
        if a.kind=='ident':
            if bi<len(e.bindings):
                pairs.append((a,e.bindings[bi])); bi+=1
    return pairs

